## Backend - app/api/routes/invoices.py

```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.invoice import Invoice
from app.models.user import User
from app.schemas.invoice import (
    InvoiceCreate,
    InvoiceUpdate,
    InvoiceResponse,
    InvoiceListResponse,
)

router = APIRouter()

@router.get("/", response_model=InvoiceListResponse)
async def list_invoices(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Invoice).filter(Invoice.user_id == current_user.id)

    if search:
        query = query.filter(Invoice.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Invoice.status == status)

    total = query.count()
    invoices = query.offset((page - 1) * limit).limit(limit).all()

    return InvoiceListResponse(
        data=invoices,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=InvoiceResponse)
async def get_invoice(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    invoice = db.query(Invoice).filter(
        Invoice.id == id,
        Invoice.user_id == current_user.id
    ).first()

    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")

    return invoice

@router.post("/", response_model=InvoiceResponse, status_code=201)
async def create_invoice(
    data: InvoiceCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    invoice = Invoice(**data.model_dump(), user_id=current_user.id)
    db.add(invoice)
    db.commit()
    db.refresh(invoice)
    return invoice

@router.put("/{id}", response_model=InvoiceResponse)
async def update_invoice(
    id: str,
    data: InvoiceUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    invoice = db.query(Invoice).filter(
        Invoice.id == id,
        Invoice.user_id == current_user.id
    ).first()

    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(invoice, key, value)

    db.commit()
    db.refresh(invoice)
    return invoice

@router.delete("/{id}", status_code=204)
async def delete_invoice(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    invoice = db.query(Invoice).filter(
        Invoice.id == id,
        Invoice.user_id == current_user.id
    ).first()

    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")

    db.delete(invoice)
    db.commit()
```

## Frontend - src/stores/invoices.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Invoice {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useInvoiceStore = defineStore('invoices', () => {
  const invoices = ref<Invoice[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchInvoices = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/invoices', { params });
      invoices.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching invoices';
    } finally {
      loading.value = false;
    }
  };

  const createInvoice = async (data: Partial<Invoice>) => {
    const { data: newInvoice } = await api.post('/invoices', data);
    invoices.value.unshift(newInvoice);
    return newInvoice;
  };

  const updateInvoice = async (id: string, data: Partial<Invoice>) => {
    const { data: updated } = await api.put(`/invoices/${id}`, data);
    const index = invoices.value.findIndex(item => item.id === id);
    if (index !== -1) {
      invoices.value[index] = updated;
    }
    return updated;
  };

  const deleteInvoice = async (id: string) => {
    await api.delete(`/invoices/${id}`);
    invoices.value = invoices.value.filter(item => item.id !== id);
  };

  return {
    invoices,
    loading,
    error,
    pagination,
    fetchInvoices,
    createInvoice,
    updateInvoice,
    deleteInvoice,
  };
});
```

