package com.postapp.controller;

import com.postapp.dto.PostDto;
import com.postapp.model.Post;
import com.postapp.service.PostService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/posts")
@RequiredArgsConstructor
public class PostController {

    private final PostService postService;

    @GetMapping
    public ResponseEntity<Page<Post>> getAll(
            @AuthenticationPrincipal UserDetails userDetails,
            Pageable pageable,
            @RequestParam(required = false) String search
    ) {
        Page<Post> posts = postService.findAll(userDetails.getUsername(), search, pageable);
        return ResponseEntity.ok(posts);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Post> getOne(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        Post post = postService.findById(id, userDetails.getUsername());
        return ResponseEntity.ok(post);
    }

    @PostMapping
    public ResponseEntity<Post> create(
            @AuthenticationPrincipal UserDetails userDetails,
            @Valid @RequestBody PostDto dto
    ) {
        Post post = postService.create(dto, userDetails.getUsername());
        return ResponseEntity.status(HttpStatus.CREATED).body(post);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Post> update(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id,
            @Valid @RequestBody PostDto dto
    ) {
        Post post = postService.update(id, dto, userDetails.getUsername());
        return ResponseEntity.ok(post);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        postService.delete(id, userDetails.getUsername());
        return ResponseEntity.noContent().build();
    }
}
