## Backend - PostService.java

```java
package com.postapp.service;

import com.postapp.dto.PostDto;
import com.postapp.exception.ResourceNotFoundException;
import com.postapp.model.Post;
import com.postapp.model.User;
import com.postapp.repository.PostRepository;
import com.postapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class PostService {

    private final PostRepository postRepository;
    private final UserRepository userRepository;

    public Page<Post> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return postRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return postRepository.findByUser(user, pageable);
    }

    public Post findById(Long id, String username) {
        User user = getUserByUsername(username);
        return postRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Post not found"));
    }

    @Transactional
    public Post create(PostDto dto, String username) {
        User user = getUserByUsername(username);
        Post post = new Post();
        post.setTitle(dto.getTitle());
        post.setDescription(dto.getDescription());
        post.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        post.setUser(user);
        return postRepository.save(post);
    }

    @Transactional
    public Post update(Long id, PostDto dto, String username) {
        Post post = findById(id, username);
        if (dto.getTitle() != null) post.setTitle(dto.getTitle());
        if (dto.getDescription() != null) post.setDescription(dto.getDescription());
        if (dto.getStatus() != null) post.setStatus(dto.getStatus());
        return postRepository.save(post);
    }

    @Transactional
    public void delete(Long id, String username) {
        Post post = findById(id, username);
        postRepository.delete(post);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
