```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Booking {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useBookingStore = defineStore('bookings', () => {
  const bookings = ref<Booking[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchBookings = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/bookings', { params });
      bookings.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching bookings';
    } finally {
      loading.value = false;
    }
  };

  const createBooking = async (data: Partial<Booking>) => {
    const { data: newBooking } = await api.post('/bookings', data);
    bookings.value.unshift(newBooking);
    return newBooking;
  };

  const updateBooking = async (id: string, data: Partial<Booking>) => {
    const { data: updated } = await api.put(`/bookings/${id}`, data);
    const index = bookings.value.findIndex(item => item.id === id);
    if (index !== -1) {
      bookings.value[index] = updated;
    }
    return updated;
  };

  const deleteBooking = async (id: string) => {
    await api.delete(`/bookings/${id}`);
    bookings.value = bookings.value.filter(item => item.id !== id);
  };

  return {
    bookings,
    loading,
    error,
    pagination,
    fetchBookings,
    createBooking,
    updateBooking,
    deleteBooking,
  };
});
```

